/* Inky Vibes: subtle bottom-right scroll guidance. */
(() => {
  function init() {
    if (document.querySelector('.scroll-hand-hint')) return;
    const host = document.querySelector('.journey .sticky');
    const journey = document.querySelector('.journey');
    if (!host || !journey) return;
    const style = document.createElement('style');
    style.textContent = "/* Quiet scroll guidance, kept clear of the centre of the scene. */\n.scroll-cue{display:none!important}\n.scroll-hand-hint{position:absolute;right:max(12px,env(safe-area-inset-right));top:auto;bottom:max(18px,env(safe-area-inset-bottom));transform:none;z-index:13;width:88px;height:88px;pointer-events:none;opacity:.12;transition:opacity .4s ease}\n.scroll-hand-hint img{display:block;width:100%;height:100%;filter:brightness(0) invert(1);animation:scroll-hand-drift 2.8s ease-in-out infinite}\n.scroll-hand-hint.is-finished{opacity:0}\n@keyframes scroll-hand-drift{0%,100%{transform:translateY(5px)}50%{transform:translateY(-5px)}}\n@media(max-width:700px){.scroll-hand-hint{width:66px;height:66px;right:max(8px,env(safe-area-inset-right));bottom:max(14px,env(safe-area-inset-bottom))}}\n@media(prefers-reduced-motion:reduce){.scroll-hand-hint img{animation:none}.scroll-hand-hint{transition:none}}\n";
    document.head.appendChild(style);
    const hint = document.createElement('div');
    hint.className = 'scroll-hand-hint';
    hint.setAttribute('role', 'img');
    hint.setAttribute('aria-label', 'Vieritä ylös tai alas');
    const image = document.createElement('img');
    image.src = "data:image/png;base64,";
    image.alt = '';
    image.setAttribute('aria-hidden', 'true');
    hint.appendChild(image);
    host.appendChild(hint);
    function update() {
      const distance = journey.offsetHeight - innerHeight;
      const progress = distance > 0 ? -journey.getBoundingClientRect().top / distance : 1;
      const hidden = progress >= .965 || matchMedia('(prefers-reduced-motion: reduce)').matches;
      hint.classList.toggle('is-finished', hidden);
      hint.setAttribute('aria-hidden', String(hidden));
    }
    addEventListener('scroll', update, { passive: true });
    addEventListener('resize', update);
    update();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();
/* Ana site içinde el simgesini alt menünün üstüne taşı */
if (window.self !== window.top) {
    const embeddedHandStyle = document.createElement("style");

    embeddedHandStyle.textContent = `
        .scroll-hand-hint {
            bottom: calc(100px + env(safe-area-inset-bottom, 0px)) !important;
        }
    `;

    document.head.appendChild(embeddedHandStyle);
}
